<script setup>
import {onMounted,ref} from 'vue';import {get,fmt,pct} from '../api/client';import DataTable from '../components/DataTable.vue';
const runs=ref([]),selected=ref(),data=ref({candidates:[],factors:[]}),showLogic=ref(false);async function load(){data.value=await get(`/predictions/${selected.value}/candidates`)}onMounted(async()=>{runs.value=await get('/predictions');if(runs.value.length){selected.value=runs.value[0].id;await load()}})
const candidates=[{label:'排名',key:'ranking'},{label:'代码',key:'stock_code'},{label:'名称',key:'stock_name'},{label:'评分',key:'score',format:v=>fmt(v,3)},{label:'上涨概率',key:'up_probability',format:pct},{label:'预计收益',key:'expected_return',format:pct},{label:'目标价',key:'target_price',format:v=>fmt(v,2)},{label:'90%收益区间',key:'return_low_90',format:(v,r)=>v==null?'—':`${pct(v)} ～ ${pct(r.return_high_90)}`},{label:'90%价格区间',key:'price_low_90',format:(v,r)=>v==null?'—':`${fmt(v,2)} ～ ${fmt(r.price_high_90,2)}`},{label:'置信度',key:'prediction_confidence',format:pct},{label:'基准收盘',key:'base_close'}];const factors=[{label:'因子',key:'factor_name'},{label:'代码',key:'factor_code'},{label:'权重',key:'model_weight',format:pct},{label:'平均IC',key:'mean_ic',format:v=>fmt(v,4)},{label:'正IC比例',key:'positive_ic_rate',format:pct}]
</script><template><div class="prediction-toolbar"><select v-if="runs.length" v-model="selected" @change="load"><option v-for="r in runs" :value="r.id">{{r.base_date}} · {{r.model_code}} {{r.model_version}}</option></select><button @click="showLogic=!showLogic">{{showLogic?'收起选股逻辑':'查看选股逻辑'}}</button></div><div class="experimental-note">上涨概率、预计收益和价格区间属于实验性估计；当前历史较短，置信度会如实显示为较低水平。</div><div v-if="showLogic" class="card logic-card"><div class="detail-heading"><h2>候选股票生成逻辑</h2><button @click="showLogic=false">收起</button></div><ol><li><b>数据范围：</b>读取日线和每日增量，按股票与交易日去重，以最新交易日作为预测基准日。</li><li><b>基础过滤：</b>排除名称包含 ST、历史少于最小天数、近20日平均成交额低于阈值的股票。</li><li><b>九个排序因子：</b>1/3/5日动量、MA5/MA20趋势、20日量比、20日成交额比、20日价格位置、10日波动率、开盘缺口。</li><li><b>候选排序：</b>使用最近交易日的 Rank IC 决定因子正负方向和权重，映射到0至100分后选出TopN。</li><li><b>收益扩展层：</b>以历史因子分位数为特征、真实次日收益为目标训练岭回归，只对候选增加预计收益。</li><li><b>上涨概率：</b>根据预计收益相对历史模型残差波动的位置估算，不是由综合评分直接转换。</li><li><b>价格和区间：</b>目标价=基准收盘×(1+预计收益)；90%区间由模型历史残差计算。</li><li><b>置信度：</b>反映训练交易日覆盖程度，不代表预测正确率；达到约120个训练交易日才会接近100%。</li><li><b>重要说明：</b>当前数据较短，收益预测为实验结果，最终应以持续的样本外正式验证为准。</li></ol></div><div class="section"><h2>候选排名与收益预期</h2><DataTable :columns="candidates" :rows="data.candidates"/></div><div class="section"><h2>因子权重</h2><DataTable :columns="factors" :rows="data.factors"/></div></template>
